        void increment(long t) {
            // Record one increment at time t
        }

        long query(long t) {
            // Number of increments with t - 1000 < timestamp <= t
            return 0;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int q = Integer.parseInt(st.nextToken());
        RollingCounter counter = new RollingCounter();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            st = new StringTokenizer(br.readLine());
            String op = st.nextToken();
            long t = Long.parseLong(st.nextToken());
            if (op.equals("inc")) counter.increment(t);
            else sb.append(counter.query(t)).append("\n");
        }
        System.out.print(sb);
    }
}
